Q = {
"20:96": "«بصرتُ بما لم یبصروا به» و «قبضة من اثر الرسول» چه می‌گوید: «الرسول» جبرئیل است یا موسی؟ و آیا این گزارش سامری ادعایی خودساخته است که متن ردش می‌کند، یا واقعیتی که تفسیر می‌پذیرد؟",
"20:97": "حکم موسی «فاذهب فان لک فی الحیاة ان تقول لا مساس» مجازاتی اجتماعی است یا طبیعی؟ و «انظر الی الهک» چه نسبتی با نابودی گوساله دارد؟ آیا «حرقه» و «نسفه» سوزاندن یک پیکر طلایی را می‌رساند یا چیزی دیگر؟",
"20:98": "چرا موسی پس از نابودیِ گوساله با جملهٔ «انما الهکم الله الذی لا اله الا هو وسع کل شیء علماً» خطاب را به قوم برمی‌گرداند؟ و علم فراگیر چه نسبتی با بطلانِ گوساله دارد؟",
"20:99": "«کذلک نقص علیک من انباء ما قد سبق» دربارهٔ روشِ قصه‌گویی قرآن چه می‌گوید؟ و «ذکراً» که «من لدنا» به پیامبر داده شده با «وقد آتیناک» چه نسبتی دارد؟",
"20:100": "«من اعرض عنه فانه یحمل یوم القیامة وزراً» اعراض از چه چیزی را مراد می‌کند: از قرآن، از ذکر، یا از دعوتِ پیامبران؟ و تعبیر «وِزر» بار تکلیف است یا بار گناه؟",
"20:101": "«خالدین فیه وساء لهم یوم القیامة حملاً» جاودانگی بار گناه را چگونه می‌فهماند؟ آیا «خلود» در این آیه به همان معنای ابدی دوزخ است، یا ماندن در بار؟",
"20:102": "«یوم ینفخ فی الصور» و «زرقاً» چه می‌گویند؟ «زرق» کبودیِ چشم است، نابینایی، یا تشنگی؟ و آیا تصویر قرآن از «مجرمین» با بقیهٔ آیات قیامت سازگار است؟",
"20:103": "«ان لبثتم الا عشراً» چه تصویری از قضاوتِ مجرمان دربارهٔ زمان می‌دهد؟ این «عشر» روزهای دنیا است، شب‌های قبر، یا فاصلهٔ دو نفخه؟",
"20:104": "«امثلهم طریقةً» چه کسی است و چرا متن حتی گفتهٔ او («الا یوماً») را در برابر «نحن اعلم بما یقولون» می‌نهد؟ آیا کم‌شمردنِ زمان نزد همهٔ گویندگان یکسان است، یا این‌جا فقط جمع‌بندی دیدگاه آنان است؟",
"20:105": "«ویسألونک عن الجبال» پرسشی واقعی از پیامبر است یا زمینه‌ای برای بیانِ قیامت؟ و «ینسفها ربی نسفاً» با «تکون کالعهن» (معارج ۹) چه نسبتی دارد؟",
"20:106": "«قاعاً صفصفاً» دو واژهٔ نادر است؛ آیا هر دو یک معنا دارند، یا مراحل زمین؟ و این تصویر از قیامت برای مخاطب عرب چه کارکردی داشت؟",
"20:107": "«لا تری فیها عوجاً ولا امتاً» وصفی هندسی است یا اخلاقی؟ و «عوج» و «امت» دو نوع ناهمواری‌اند یا دو سطح (مکانی و کیفی)؟",
"20:108": "«یتبعون الداعی لا عوج له» داعی کیست و چرا صداها «خشعت للرحمن» می‌شوند؟ و «همساً» چیست: آهسته‌ترین صدا، صدای قدم‌ها، یا زمزمه؟",
"20:109": "«لا تنفع الشفاعة الا من اذن له الرحمن ورضی له قولاً» دو شرط می‌گذارد؛ این «قول» به چه چیزی اشاره دارد: شهادت توحید، سخن شفیع، یا شخصِ شفاعت‌شونده؟ و این آیه با آیات نفی مطلق شفاعت چگونه جمع می‌شود؟",
"20:110": "ضمیرِ «یعلم ما بین ایدیهم وما خلفهم ولا یحیطون به علماً» به چه کسی برمی‌گردد: فرشتگان، گنهکاران، یا همهٔ آفریدگان؟ و نفی «احاطه» در علم چه چیزی را از بحث شفاعت جدا می‌کند؟",
"20:111": "«وعنت الوجوه للحی القیوم» چه نسبتی با «وقد خاب من حمل ظلماً» دارد؟ «عنت» به معنای تسلیم است یا خواری؟ و آیا «ظلم» در اینجا شرک است یا هر ستمی؟",
"20:112": "«فلا یخاف ظلماً ولا هضماً» دو نوع ترس را از مؤمنِ عمل‌کننده نفی می‌کند؛ تفاوت «ظلم» (افزودنِ گناه) و «هضم» (کاستنِ ثواب) در ساختار آیه چیست؟",
"20:113": "«قرآناً عربیاً وصرفنا فیه من الوعید» به زبان قرآن و تنوعِ هشدار اشاره دارد؛ چه نسبتی میان «عربی» بودن و «لعلهم یتقون او یحدث لهم ذکراً» است؟",
"20:114": "«فتعالی الله الملک الحق» و نهی از «لا تعجل بالقرآن» چه پیوندی دارند؟ شتاب پیامبر در خواندن، برای حفظ بود یا برای ابلاغ؟ و «وقل رب زدنی علماً» چه جایگاهی در ادب فراگیری دارد؟",
"20:115": "«عهدنا الی آدم من قبل فنسی» به چه عهدی اشاره دارد؟ «نسی» فراموشی است یا ترک؟ و «لم نجد له عزماً» مسئولیتِ آدم را چگونه برآورد می‌کند؟",
"20:116": "چرا قصهٔ آدم در این سوره با «فسجدوا الا ابلیس ابی» تکرار می‌شود، و «ابی» چه تفاوتی با «استکبر» (بقره ۳۴) دارد؟",
"20:117": "«ان هذا عدو لک ولزوجک فلا یخرجنکما من الجنة فتشقی» چرا هشدار را به آدم می‌دهد و در شقاوت فقط او را می‌آورد؟ آیا مسئولیت مرد در معیشت است یا این صرفاً تعبیر نحوی است؟",
"20:118": "نعمت‌های «لا تجوع ولا تعری» چه تصویری از بهشت آدم می‌دهد؟ آیا این بهشت همان بهشتِ آخرت است یا جایی زمینی؟",
"20:119": "«لا تظمأ فیها ولا تضحی» دو نیازِ دیگر را نفی می‌کند؛ این چهار نفی (جوع، عری، ظمأ، ضحی) چه معیاری برای تعریفِ «بهشت» می‌دهند؟",
"20:120": "«شجرة الخلد وملک لا یبلی» چه چیز را وعده می‌دهد؟ چرا شیطان در این سوره «شجرة الخلد» می‌گوید، در حالی که اعراف ۲۰ «ملکین او خالدین» دارد؟",
"20:121": "«وطفقا یخصفان علیهما من ورق الجنة» و «وعصی آدم ربه فغوی» آیا خطای آدم را معصیت می‌خواند؟ و واژهٔ «غوی» با مقام نبوت چگونه سنجیده می‌شود؟",
"20:122": "«ثم اجتباه ربه فتاب علیه وهدی» ترتیب «اجتباء»، «توبه» و «هدایت» چه می‌گوید؟ آیا پذیرش توبه پیش از شروع هدایت است یا پس از آن؟",
"20:123": "«اهبطا منها جمیعاً بعضکم لبعض عدو» خطاب «اهبطا» دو نفر است و «جمیعاً» و «بعضکم» جمع؛ این تغییر ضمیر به چه کسانی اشاره دارد؟ و «فمن اتبع هدای فلا یضل ولا یشقی» با سخنِ ۱۱۷ چه رابطه‌ای دارد؟",
"20:124": "«معیشة ضنکاً» تنگی روزی است، عذاب قبر یا تنگی روحی؟ و رابطه‌اش با «اعرض عن ذکری» چیست؟ آیا تنگی ربطی به فقر دارد؟",
"20:125": "پرسش «لم حشرتنی اعمی وقد کنت بصیراً» از نابینایی ظاهری سخن می‌گوید یا باطنی؟ و آیا این گفت‌وگو را باید خبری از قیامت دانست، یا تمثیلی از حال اعراض؟",
"20:126": "پاسخ «کذلک اتتک آیاتنا فنسیتها وکذلک الیوم تنسی» چه معیاری برای عدالت می‌دهد: جزای از جنس عمل؟ و آیا «نسیان» الهی به معنی ترک است یا رها کردن؟",
"20:127": "«من اسرف ولم یؤمن بآیات ربه» جزای «اسراف» را با «عدم ایمان» پیوند می‌دهد؛ این اسراف مالی است، یا اسراف در گناه؟ و عذاب آخرت چرا «اشد وابقی» است؟",
"20:128": "«افلم یهد لهم کم اهلکنا قبلهم من القرون یمشون فی مساکنهم» چه معیار تاریخی-عبرتی می‌دهد؟ آیا این هدایت با دیدن آثارِ اقوام پیشین حاصل می‌شود یا به عقل بازمی‌گردد؟",
"20:129": "«ولولا کلمة سبقت من ربک ولکان لزاماً واجل مسمی» به چه کلمه‌ای اشاره دارد؟ و تأخیر عذاب را چگونه با عدالت و حکمت جمع می‌کند؟",
"20:130": "«فاصبر علی ما یقولون وسبح بحمد ربک» چه نسبتی میان صبر و تسبیح می‌گذارد؟ ذکر زمان‌ها (قبل طلوع، قبل غروب، آناء اللیل، اطراف النهار) نمازهای پنج‌گانه را می‌رساند یا اذکارِ دیگر؟",
"20:131": "«ولا تمدن عینیک الی ما متعنا به ازواجاً منهم» نهی از چشم‌دوختن به زینت دنیا است؛ «ازواجاً» در اینجا گروه‌ها است یا همسران؟ و این نهی چه نسبتی با «لنفتنهم فیه» دارد؟",
"20:132": "«وأمر اهلک بالصلاة واصطبر علیها لا نسألک رزقاً نحن نرزقک» نماز را به خانواده می‌رساند؛ چرا در همان آیه از روزی سخن می‌رود؟ آیا میان نماز و روزی رابطه‌ای اراده شده است؟",
"20:133": "«لولا یأتینا بآیة من ربه» درخواست معجزه است؛ پاسخ «اولم تأتهم بینة ما فی الصحف الاولی» معجزه را چگونه تعریف می‌کند؟ و «الصحف الاولی» چه نقشی در اثبات حقانیت قرآن دارد؟",
"20:134": "«لو انا اهلکناهم بعذاب من قبله لقالوا ربنا لولا ارسلت الینا رسولاً» چه چیزی را درباره اتمام حجت می‌گوید؟ آیا بدون رسول عذاب جایز نیست، یا آیه فقط توجیهِ ارسال است؟",
"20:135": "«کل متربص فتربصوا» چه نسبتی میان انتظار پیامبر و انتظار مخالفان می‌گذارد؟ و «اصحاب الصراط السوی» و «من اهتدی» چه معیاری برای داوری نهایی‌اند؟",
}
